'use strict';
const M=window.N2Model,$=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='n2-private-review-additions-v1';let data,base,local=[],tab='mistakes',topic='',limit=20;
const modeNames={baseline:'首次作答基线',independent:'严格首次独立',assisted:'提示 / 讲解后 / 复测',all:'全部混合条件'};
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,7000)}
function filters(){return {mode:$('mode').value,module:$('module').value,from:$('from').value,to:$('to').value}}
function gauge(rows){const s=M.stats(rows),value=s.rate===null?'—':(s.rate*100).toFixed(1),dash=s.rate===null?0:s.rate*100;return `<div class="gauge" role="img" aria-label="${s.total?value+'%，'+s.correct+' / '+s.total+' 题正确':'暂无可评分记录'}"><svg viewBox="0 0 240 150" aria-hidden="true"><path class="track" d="M 22 124 A 98 98 0 0 1 218 124" fill="none" stroke-width="12" stroke-linecap="round"/><path class="fill" d="M 22 124 A 98 98 0 0 1 218 124" fill="none" stroke-width="12" stroke-linecap="round" pathLength="100" stroke-dasharray="${dash} 100" ${dash?'':'style="opacity:0"'}/></svg><div class="gauge-value">${value}${s.rate===null?'':'<small>%</small>'}</div></div><div class="gauge-denom">${s.total?`<strong>${s.correct}</strong> / ${s.total} 题正确`:'暂无可评分记录 · 分母 0'}</div>`}
function render(){const f=filters(),rows=M.filter(data,f),reviewRows=M.filter(data,{...f,mode:'all'}),stats=M.stats(rows),ranks=M.rank(reviewRows),dates=rows.map(a=>a.date).sort();$('modeBadge').textContent=modeNames[f.mode];$('overallGauge').innerHTML=gauge(rows);$('overallNote').textContent=f.mode==='baseline'?'N3 教材 / Monoxer 历史题 · 非 N2 模考 · 提示条件未核实':f.mode==='independent'?'仅计未提示的首次独立作答':'当前条件仅供复盘，不与首次作答基线混算';$('moduleGauges').innerHTML=M.modules.map((m,i)=>`<article class="module-card panel"><div class="module-head"><h3>${M.labels[m]}</h3><span>${['GRAMMAR','READING','VOCABULARY','LISTENING'][i]}</span></div>${gauge(rows.filter(a=>a.module===m))}${!rows.some(a=>a.module===m)?'<p class="module-empty">'+(data.attempts.some(a=>a.module===m)?'已有其他条件记录，未纳入当前口径':'尚无核验成绩 · 未测')+'</p>':''}</article>`).join('');$('windowNote').textContent=`统计窗口：${f.from||dates[0]||'无记录'} — ${f.to||dates.at(-1)||'无记录'} · ${modeNames[f.mode]} · ${stats.total} 道可评分记录`;$('calculationNote').textContent='整体 = 正确题数 ÷ 有效题数，不是模块百分比的平均。部分正确按错误计；未测不记 0%。一条多要素任务记 1 题；截图题与复测题的条件分别保留。';$('weakCount').textContent=ranks.length+' 个';$('weaknesses').innerHTML=ranks.length?ranks.map((g,i)=>`<button class="weak-row ${topic===g.key?'selected':''}" data-key="${esc(g.key)}"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="weak-copy"><strong>${esc(g.label)}</strong><small>${M.labels[g.module]} · ${g.independent?'独立 '+g.independent+' · ':''}${g.external?'条件未核实 '+g.external+' · ':''}${g.assisted?'提示/复测 '+g.assisted:''}</small></span><span class="error-count">${g.count}<small>次错误</small></span></button>`).join(''):'<div class="empty">当前范围没有可核验的错误记录。<br>没有记录不代表已经掌握。</div>';$('mistakeCount').textContent=reviewRows.filter(a=>a.result!=='correct').length;$('clearTopic').hidden=!topic;$('selectedTopic').innerHTML=topic?`<div class="selected-topic">正在查看：${esc(M.keyLabel(topic))} · 错因以原始记录为准</div>`:'';
const search=$('search').value.trim().toLowerCase();let visible=reviewRows.filter(a=>(tab==='history'||a.result!=='correct')&&(!topic||M.keys(a).includes(topic))&&(!search||[a.prompt,a.canonical_key,a.error_reason,a.user_answer,a.expected_answer,...a.error_tags.map(t=>M.tags[t]||t)].join(' ').toLowerCase().includes(search)));const priorities=new Map(ranks.map(g=>[g.key,g.count]));visible.sort((a,b)=>tab==='history'?b.date.localeCompare(a.date)||a.id.localeCompare(b.id):Math.max(0,...M.keys(b).map(k=>priorities.get(k)||0))-Math.max(0,...M.keys(a).map(k=>priorities.get(k)||0))||b.date.localeCompare(a.date)||a.id.localeCompare(b.id));$('attempts').innerHTML=visible.length?visible.slice(0,limit).map(attemptCard).join(''):'<div class="empty">当前筛选下暂无记录。<br>可切换作答口径，或清除筛选查看已保存的内容。</div>';$('more').hidden=visible.length<=limit;$('more').textContent=`显示更多记录 ↓（还有 ${Math.max(0,visible.length-limit)} 条）`;document.querySelectorAll('.weak-row').forEach(b=>b.onclick=()=>{topic=b.dataset.key;limit=20;render();$('selectedTopic').scrollIntoView({behavior:'smooth',block:'center'})});}
function attemptCard(a){const support=a.support==='unknown_external'?'外部截图 · 提示条件未核实':a.support==='hinted'?'有提示':a.support==='immediate'?'刚讲后作答':a.attempt_kind==='retest'?'无提示复测':'首次独立';return `<article class="attempt"><div class="attempt-top"><div><span class="chip">${M.labels[a.module]}</span><span class="chip ${a.result==='correct'?'right':'wrong'}">${{correct:'正确',incorrect:'错误',partial:'部分正确 · 计错'}[a.result]}</span>${esc(support)}</div><time>${esc(a.date)}</time></div><h4>${esc(a.prompt)}</h4>${Array.isArray(a.options)?'<ol class="options">'+a.options.map(o=>'<li>'+esc(o)+'</li>').join('')+'</ol>':''}<div class="answer"><span>你的作答 <strong>${esc(a.user_answer||'原记录未提供')}</strong></span><span>核对答案 <strong>${esc(a.expected_answer||'见原始批改记录')}</strong></span></div><details><summary>查看错因与来源</summary><p><strong>原因 / 观察：</strong>${esc(a.error_reason||'没有记录错误原因；不自动推断。')}</p>${a.choice_result?`<p>选项结果：${esc(a.choice_result)} · 理解结果：${esc(a.comprehension_result||'未记录')}</p>`:''}<p>${esc(a.notes||'')}</p><p>来源：${esc(a.source_label||a.date+' 课堂作答记录')}<br>记录 ID：${esc(a.id)}<br>来源标识：${a.source_ids.map(esc).join('；')}</p></details></article>`}
function download(obj){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='n2-review-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function localStatus(){ $('localStatus').textContent=local.length?`此设备浏览器另存 ${local.length} 条记录。未上传、未跨设备同步；请导出备份。`:'当前为私密发布快照。公开 GitHub 自动同步已关闭；聊天新增作答需整理后导入或重新发布。'}
async function start(){try{const response=await fetch('data.json',{cache:'no-store'});if(!response.ok)throw Error('快照加载失败');base=M.validate(await response.json());data=base;try{const stored=JSON.parse(localStorage.getItem(STORE)||'[]');if(stored.length){data=M.merge(base,{schema_version:'1.0',attempts:stored}).data;local=stored.filter(a=>!base.attempts.some(b=>b.id===a.id))}}catch(e){toast('设备缓存未加载：'+e.message+'。已保留原缓存，请先导出原有备份。')}$('snapshotDate').textContent=(base.generated_at||'').slice(0,10)||'日期未记录';$('scope').textContent=base.scope?.description||'仅覆盖本次导入的记录，不代表全部历史。';$('provenance').innerHTML='<p>来源：用户照片逐题批改与可追溯聊天记录；每题展开可查看来源标识。旧版记录单独保留，不与新表自动拼接，以免重复计数。</p><p>尚未完整迁移此前课程、旧测评与所有作答历史。当前听力无核验完成音频成绩；计划不计完成，准确率不代表掌握率或通过概率。</p>';localStatus();render();window.dispatchEvent(new CustomEvent('n2-records-ready',{detail:data}));}catch(e){$('overallGauge').innerHTML='<div class="empty" style="color:white">'+esc(e.message)+'</div>';toast('无法读取数据，未显示任何模拟成绩。')}}
['mode','module','from','to'].forEach(id=>$(id).addEventListener('change',()=>{topic='';limit=20;render()}));$('search').addEventListener('input',()=>{limit=20;render()});$('reset').onclick=()=>{$('mode').value='baseline';$('module').value='all';$('from').value='';$('to').value='';$('search').value='';topic='';limit=20;render()};$('clearTopic').onclick=()=>{topic='';render()};$('more').onclick=()=>{limit+=30;render()};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;limit=20;document.querySelectorAll('[data-tab]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))});render()});$('export').onclick=()=>{if(data)download({...data,exported_at:new Date().toISOString(),export_note:'含当前设备导入记录；原快照 scope 仅说明原始发布覆盖范围，导入记录以各项日期与 source_ids 为准。'})};$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(!data)throw Error('请等待快照加载');if(file.size>5*1024*1024)throw Error('文件超过 5 MB');const incoming=M.validate(JSON.parse(await file.text())),merged=M.merge(data,incoming),extra=merged.data.attempts.filter(a=>!base.attempts.some(b=>b.id===a.id));localStorage.setItem(STORE,JSON.stringify(extra));data=merged.data;local=extra;localStatus();render();window.dispatchEvent(new CustomEvent('n2-records-ready',{detail:data}));toast('合并完成：新增 '+merged.added+' 条；相同 ID 的相同记录已去重。')}catch(error){toast('导入失败，原记录未改变：'+error.message)}finally{e.target.value=''}};start();

window.getN2Attempts=()=>data?.attempts||[];
